import sys
from collections import deque

def main():
    n, k = map(int, sys.stdin.readline().split())
    pos_perms = []
    for _ in range(k):
        perm = list(map(int, sys.stdin.readline().split()))
        pos = [0] * (n + 1)  # 1-based indexing
        for idx, num in enumerate(perm):
            pos[num] = idx
        pos_perms.append(pos)

    # Build adjacency list
    adj = [[] for _ in range(n+1)]  # 1-based
    for a in range(1, n+1):
        for b in range(1, n+1):
            if a == b:
                continue
            if all(p[a] < p[b] for p in pos_perms):
                adj[a].append(b)

    # Compute in-degrees and perform Kahn's algorithm for topological sort
    in_degree = [0] * (n + 1)
    for u in range(1, n+1):
        for v in adj[u]:
            in_degree[v] += 1

    q = deque()
    for i in range(1, n+1):
        if in_degree[i] == 0:
            q.append(i)

    topo_order = []
    while q:
        u = q.popleft()
        topo_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    # Compute longest path using dynamic programming
    dp = [1] * (n + 1)
    for u in topo_order:
        for v in adj[u]:
            if dp[v] < dp[u] + 1:
                dp[v] = dp[u] + 1

