def can_recover_bst(a):
    n = len(a)
    if n < 2:
        return "Yes"

    # Precompute gcd_ok matrix
    gcd_ok = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if math.gcd(a[i], a[j]) > 1:
                gcd_ok[i][j] = True

    # Precompute mask_gcd for each index; mask_gcd[k] has bits set for all m where gcd(a[k],a[m])>1
    mask_gcd = [0] * n
    for k in range(n):
        for m in range(n):
            if gcd_ok[k][m]:
                mask_gcd[k] |= (1 << m)

    # Initialize mask_table with base cases (single-element intervals)
    mask_table = [[0] * n for _ in range(n)]
    for i in range(n):
        mask_table[i][i] = 1 << i

    # Fill mask_table for intervals of increasing length
    for L in range(2, n + 1):
        for l in range(n - L + 1):
            r = l + L - 1
            current_mask = 0
            for k in range(l, r + 1):
                valid = True

                # Check left sub-interval [l, k-1]
                if k > l:
                    left_l = l
                    left_r = k - 1
